/**
 * WordPress dependencies
 */
import { useCallback, useEffect, useRef, useState } from '@wordpress/element';
import { useSelect } from '@wordpress/data';
/**
 * External dependencies
 */
import { getAgentManager } from '@automattic/agenttic-client';
/**
 * Internal dependencies
 */
import agentConfigFactory from '../../ai/wp-orchestrator';
// @ts-expect-error - JS file without type definitions
import { store as aiStore } from '@store';
export const AGENT_ID = 'wp-orchestrator';
const AGENT_POLL_INTERVAL_MS = 100;
const AGENT_POLL_MAX_ATTEMPTS = 50;
// Module-level initialization state to prevent race conditions
// when multiple components call useSharedAgentConfig simultaneously
let initializationPromise = null;
let initializedBackend = null;
let initializedSessionId = null;
function resetInitializationState() {
    initializationPromise = null;
    initializedBackend = null;
    initializedSessionId = null;
}
/**
 * Check if Agents Manager should handle the agent (set by PHP).
 */
function isAgentsManagerEnabled() {
    return !!window.bigSkyImageStudio?.isUnifiedChatEnabled;
}
/**
 * Wait for Agents Manager to expose the agentManager and create the agent.
 * Polls until the agent is available or times out.
 */
async function waitForAgentsManager() {
    // Check if agent already exists
    if (window.__agentManager?.hasAgent(AGENT_ID)) {
        // eslint-disable-next-line no-console
        console.log('[Image Studio] Agent already exists (created by Agents Manager)');
        return window.__agentManager;
    }
    for (let attempt = 0; attempt < AGENT_POLL_MAX_ATTEMPTS; attempt++) {
        await new Promise((resolve) => setTimeout(resolve, AGENT_POLL_INTERVAL_MS));
        if (window.__agentManager?.hasAgent(AGENT_ID)) {
            return window.__agentManager;
        }
    }
    return null;
}
function getAgentManagerForBackend(backendType) {
    switch (backendType) {
        case 'agents-manager':
            return window.__agentManager ?? null;
        case 'headless':
            return getAgentManager();
        default:
            return null;
    }
}
/**
 * Hook that uses the WP Orchestrator agent.
 * - If Agents Manager is enabled (bigSkyImageStudio.isUnifiedChatEnabled): uses the shared agent
 * - Otherwise: creates agent directly (headless mode)
 */
export function useSharedAgentConfig() {
    const [messages, setMessages] = useState([]);
    const [isProcessing, setIsProcessing] = useState(false);
    const [progressMessage, setProgressMessage] = useState(null);
    const [currentPhase, setCurrentPhase] = useState(null);
    const [error, setError] = useState(null);
    const [suggestions, setSuggestions] = useState([]);
    const [isReady, setIsReady] = useState(false);
    const [backendType, setBackendType] = useState(null);
    const abortControllerRef = useRef(null);
    const sessionId = useSelect((select) => select(aiStore).getSessionId() ||
        'wp-orchestrator-default', []);
    useEffect(() => {
        let mounted = true;
        async function initHeadless() {
            // eslint-disable-next-line no-console
            console.log('[Image Studio] Using headless Big Sky orchestrator');
            const agentManager = getAgentManager();
            const config = await agentConfigFactory.createAgentConfig(sessionId);
            if (!agentManager.hasAgent(AGENT_ID)) {
                await agentManager.createAgent(AGENT_ID, config);
            }
            return 'headless';
        }
        async function doInitialize() {
            // Check server-side flag first
            if (!isAgentsManagerEnabled()) {
                // eslint-disable-next-line no-console
                console.log('[Image Studio] Agents Manager not enabled, using headless');
                return initHeadless();
            }
            // eslint-disable-next-line no-console
            console.log('[Image Studio] Agents Manager enabled, waiting for agent...');
            // Wait for Agents Manager to create the agent
            const manager = await waitForAgentsManager();
            if (manager) {
                return 'agents-manager';
            }
            // Fallback if Agents Manager didn't create the agent in time
            return initHeadless();
        }
        function setReadyState(backend) {
            if (mounted) {
                setBackendType(backend);
                setIsReady(true);
            }
        }
        async function initialize() {
            try {
                const sessionChanged = initializedSessionId &&
                    initializedSessionId !== sessionId &&
                    initializedBackend === 'headless';
                if (sessionChanged) {
                    // eslint-disable-next-line no-console
                    console.log('[Image Studio] Session changed, reinitializing agent');
                    resetInitializationState();
                }
                if (initializedBackend &&
                    initializedSessionId === sessionId) {
                    setReadyState(initializedBackend);
                    return;
                }
                if (initializationPromise) {
                    const backend = await initializationPromise;
                    setReadyState(backend);
                    return;
                }
                initializationPromise = doInitialize();
                const backend = await initializationPromise;
                initializedBackend = backend;
                initializedSessionId = sessionId;
                setReadyState(backend);
            }
            catch (err) {
                resetInitializationState();
                if (mounted) {
                    // eslint-disable-next-line no-console
                    console.error('[Image Studio] Failed to initialize agent:', err);
                    setError(err);
                }
            }
        }
        initialize();
        return () => {
            mounted = false;
            abortControllerRef.current?.abort();
        };
    }, [sessionId]);
    const onSubmit = useCallback(async (message) => {
        if (!isReady || !backendType) {
            setError(new Error('AI assistant is still loading. Please try again.'));
            return;
        }
        const userMessage = {
            id: `user-${Date.now()}`,
            role: 'user',
            content: [{ type: 'text', text: message }],
        };
        setMessages((prev) => [...prev, userMessage]);
        setIsProcessing(true);
        setError(null);
        setProgressMessage(null);
        setCurrentPhase(null);
        abortControllerRef.current = new AbortController();
        try {
            const assistantMessageId = `assistant-${Date.now()}`;
            let hasAddedAssistantMessage = false;
            function updateAssistantMessage(text) {
                const content = [{ type: 'text', text }];
                if (hasAddedAssistantMessage) {
                    setMessages((prev) => prev.map((msg) => msg.id === assistantMessageId
                        ? { ...msg, content }
                        : msg));
                }
                else {
                    setMessages((prev) => [
                        ...prev,
                        {
                            id: assistantMessageId,
                            role: 'assistant',
                            content,
                        },
                    ]);
                    hasAddedAssistantMessage = true;
                }
            }
            const agentManager = getAgentManagerForBackend(backendType);
            if (!agentManager) {
                throw new Error('Agent manager not available');
            }
            const streamOptions = backendType === 'agents-manager'
                ? {
                    withHistory: true,
                    signal: abortControllerRef.current.signal,
                }
                : { abortSignal: abortControllerRef.current.signal };
            for await (const update of agentManager.sendMessageStream(AGENT_ID, message, streamOptions)) {
                const progressPart = update?.status?.message?.parts?.find((part) => part.type === 'progress');
                if (progressPart?.data?.summary) {
                    setProgressMessage(progressPart.data.summary);
                }
                if (progressPart?.data?.phase === 'uploading') {
                    setCurrentPhase('uploading');
                }
                if (update?.text) {
                    updateAssistantMessage(update.text);
                    if (update.final) {
                        break;
                    }
                }
            }
        }
        catch (err) {
            if (err.name !== 'AbortError') {
                setError(err);
            }
        }
        finally {
            setIsProcessing(false);
            setProgressMessage(null);
            setCurrentPhase(null);
            abortControllerRef.current = null;
        }
    }, [isReady, backendType]);
    const abortCurrentRequest = useCallback(() => {
        abortControllerRef.current?.abort();
        abortControllerRef.current = null;
        getAgentManagerForBackend(backendType)?.abortCurrentRequest(AGENT_ID);
    }, [backendType]);
    const registerSuggestions = useCallback((newSuggestions) => {
        setSuggestions(newSuggestions);
    }, []);
    const clearSuggestions = useCallback(() => {
        setSuggestions([]);
    }, []);
    return {
        messages,
        isProcessing,
        progressMessage,
        currentPhase,
        error,
        onSubmit,
        abortCurrentRequest,
        registerSuggestions,
        clearSuggestions,
        suggestions,
    };
}
