/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import { getAssistantById } from '@ai/assistants/assistant-registry';
import { requestJetpackToken } from '@utils/request-jetpack-token.ts';
import log from '@utils/log-debug.js';

/**
 * Sort message history to ensure proper ordering of tool calls and responses
 * Moved from useAssistantChat hook to store action
 *
 * @param {Array} messagesArray - Array of messages to sort
 * @return {Array} Sorted messages array
 */
const sortMessageHistory = ( messagesArray ) => {
	const sortedMessages = [ ...messagesArray ];
	sortedMessages.sort( ( a, b ) => a.created_at - b.created_at );

	// Move tool messages after their corresponding assistant messages
	for ( let i = 0; i < sortedMessages.length; i++ ) {
		if (
			sortedMessages[ i ].role === 'assistant' &&
			sortedMessages[ i ].tool_calls &&
			sortedMessages[ i ].tool_calls.length > 0
		) {
			let insertIndex = i + 1;
			for ( let j = i + 1; j < sortedMessages.length; j++ ) {
				if (
					sortedMessages[ j ].role === 'tool' &&
					sortedMessages[ i ].tool_calls.some(
						( call ) => call.id === sortedMessages[ j ].tool_call_id
					)
				) {
					const toolMessage = sortedMessages.splice( j, 1 )[ 0 ];
					sortedMessages.splice( insertIndex, 0, toolMessage );
					insertIndex++;
				}
			}
		}
	}

	return sortedMessages;
};

/**
 * Get current context for an assistant
 * Moved from useAssistantChat hook to store action
 *
 * @param {Object}   assistant   - The assistant object
 * @param {Function} getContexts - Function to get contexts from store
 * @return {Object} Current context for the assistant
 */
const getCurrentContext = ( assistant, getContexts ) => {
	return getContexts()[ assistant.id ];
};

/**
 * Get system prompt for an assistant
 * Moved from useAssistantChat hook to store action
 *
 * @param {Object}   assistant   - The assistant object
 * @param {Function} getContexts - Function to get contexts from store
 * @return {string} System prompt for the assistant
 */
const getSystemPrompt = ( assistant, getContexts ) => {
	const context = getCurrentContext( assistant, getContexts );
	return typeof assistant.instructions === 'function'
		? assistant.instructions( context )
		: assistant.instructions;
};

/**
 * Get tools for an assistant
 * Moved from useAssistantChat hook to store action
 *
 * @param {Object}   assistant   - The assistant object
 * @param {Function} getContexts - Function to get contexts from store
 * @return {Array} Array of OpenAI-formatted tools
 */
const getTools = ( assistant, getContexts ) => {
	const toolkit = assistant?.toolkits[ 0 ];
	if ( ! toolkit ) {
		throw new Error( 'Toolkit not found' );
	}

	const context = getCurrentContext( assistant, getContexts );
	const tools =
		typeof toolkit?.tools === 'function'
			? toolkit.tools( context )
			: toolkit.tools;

	const openaiTools = tools.map( ( tool ) => {
		if ( tool.parameters && tool.strict !== undefined ) {
			tool.parameters.additionalProperties = ! tool.strict;
		}
		return {
			type: 'function',
			function: tool,
		};
	} );

	return openaiTools;
};

/**
 * Execute a tool callback
 * Moved from useAssistantChat hook to store action
 *
 * @param {string} assistantId - The assistant ID
 * @param {string} toolName    - The tool name to execute
 * @param {Object} args        - Arguments for the tool
 * @param {string} request     - Original user request
 * @param {string} id          - Tool call ID
 * @return {Function} Redux thunk action
 */
export const executeToolCallback =
	( assistantId, toolName, args, request, id = null ) =>
	async ( { select, dispatch } ) => {
		dispatch.incrementPendingToolCallbacks();

		try {
			const callbacks = select.getCallbacks();

			if (
				callbacks[ assistantId ] &&
				callbacks[ assistantId ][ toolName ]
			) {
				return await callbacks[ assistantId ][ toolName ]( {
					...args,
					__original_request: request,
					__original_id: id,
				} );
			}

			throw new Error( `Callback ${ toolName } not found` );
		} finally {
			dispatch.decrementPendingToolCallbacks();
		}
	};

/**
 * Main assistant chat implementation
 * Moved from useAssistantChat hook to store action
 *
 * @param {string} userMessage - The user message
 * @return {Function} Redux thunk action
 */
export const runAssistantChat =
	( userMessage ) =>
	async ( { select, dispatch } ) => {
		// Get required data from store
		const getMessages = select.getMessages;
		const getAssistant = select.getAssistant;
		const getContexts = select.getContexts;
		const chatModel = select.getAdvancedChatModel();

		// Filter out messages with content type "component"
		const filteredMessages = getMessages().filter( ( message ) => {
			if ( Array.isArray( message.content ) ) {
				return ! message.content.some(
					( item ) => item.type === 'component'
				);
			}
			// Keep all other messages
			return true;
		} );

		const sortedMessages = sortMessageHistory( filteredMessages );
		const currentAssistant = getAssistantById( getAssistant() );

		let response;

		if ( currentAssistant.prompt ) {
			// Use prompt-query endpoint for assistants with custom prompts
			const jetpackToken = await requestJetpackToken();
			const context = getCurrentContext( currentAssistant, getContexts );

			response = await (
				await fetch(
					`https://public-api.wordpress.com/wpcom/v2/big-sky/prompt-query`,
					{
						method: 'POST',
						headers: {
							Authorization: `Bearer ${ jetpackToken.token }`,
							'Content-Type': 'application/json',
						},
						body: JSON.stringify( {
							prompt: currentAssistant.prompt,
							context: {
								userLanguage: 'en-US',
								messages: sortedMessages,
								userMessage,
								...context,
							},
							big_sky_version:
								window?.bigSkyInitialState?.bigSkyVersion ??
								'0',
						} ),
					}
				)
			).json();
		} else {
			// Use chat completion for assistants with standard instructions
			const systemPrompt = getSystemPrompt(
				currentAssistant,
				getContexts
			);
			const chatMessages = [
				{
					role: 'system',
					content: systemPrompt,
				},
				...sortedMessages,
			];

			const tools = getTools( currentAssistant, getContexts );

			response = await dispatch.runChatCompletion(
				chatModel,
				chatMessages,
				tools
			);
		}

		// Show free trial warning if needed
		if ( response?.usage?.big_sky?.show_free_trial_warning ) {
			dispatch.assistantSay(
				__( 'You have used 15 of your 30 free AI requests.', 'big-sky' )
			);
		}

		// Handle tool calls
		const toolCalls = response?.choices?.[ 0 ]?.message?.tool_calls;
		if ( ! toolCalls || toolCalls.length === 0 ) {
			// Return text response if no tool calls
			const messageContent = response?.choices?.[ 0 ]?.message?.content;
			if ( messageContent ) {
				dispatch.deleteMarkedMessages();
				return messageContent;
			}

			log.error( `No text or tool call response from AI.` );
			return;
		}

		// Add assistant message with tool calls to the store
		dispatch.assistantSay( '', {
			tool_calls: toolCalls,
			id: response?.id,
			created_at: response?.created_at || Date.now() / 1000,
		} );

		// Process tool calls
		for ( const [ index, toolCall ] of toolCalls.entries() ) {
			const args = toolCall.function.arguments;

			try {
				const parsedArgs = JSON.parse( args );
				const result = await dispatch.executeToolCallback(
					currentAssistant.id,
					toolCall.function.name,
					parsedArgs,
					userMessage,
					response?.id
				);

				// Return result of last tool call
				if ( index === toolCalls.length - 1 ) {
					return result;
				}
			} catch ( e ) {
				log.error(
					`Error running callback for ${ toolCall.function.name }:`,
					e
				);
			} finally {
				// Add tool message to maintain conversation history
				dispatch.addMessage( {
					role: 'tool',
					id: `tc:${ toolCall.id }`,
					created_at: Date.now() / 1000,
					tool_call_id: toolCall.id,
					content: '',
				} );
			}
		}
		dispatch.deleteMarkedMessages();
	};
