/**
 * WordPress dependencies
 */
import { dispatch, select } from '@wordpress/data';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { store as blocksStore } from '@wordpress/blocks';
/**
 * Internal dependencies
 */
import { STORE_NAME as AI_STORE } from '../../store/constants';
import { getCurrentPageContent } from '../utils/agent-helpers';
const CORE_STORE = 'core';
const EDITOR_STORE = 'core/editor';
/**
 * Model override for CIAB Admin environment.
 * Set to a model name to use a different model for CIAB Admin, or null to use the default.
 * This is passed via constructorArguments to the backend agent.
 */
const CIAB_ADMIN_MODEL = 'gpt-5.2';
const CIAB_ADMIN_REASONING_EFFORT = 'low'; // 'none' | 'low' | 'medium' | 'high'
/**
 * Store name for the AI agent context store registered by ciab-admin.
 * This must match the STORE_NAME constant exported from @automattic/ai-agent package.
 * @see https://github.com/Automattic/ciab-admin/blob/trunk/packages/ai-agent/src/store/index.ts
 */
const AI_AGENT_CONTEXT_STORE = 'ai-agent-context';
const IMAGE_STUDIO_STORE = 'image-studio';
/**
 * Detect the current admin environment
 * Returns 'image-studio' if the Image Studio modal is open
 * Returns 'ciab-admin' if the user is in the CIAB Admin interface (Next Admin plugin is installed, active, and user is on /new route)
 * Returns 'wp-admin' otherwise
 *
 * Supports both pretty permalinks (/wp-admin/new/...) and plain permalinks (/wp-admin/admin.php?page=next-admin&...)
 *
 * @return The environment identifier
 */
function detectEnvironment() {
    try {
        const aiAgentContextStore = select(AI_AGENT_CONTEXT_STORE);
        const pathname = window.location.pathname;
        const search = window.location.search;
        const isImageStudioOpen = select(IMAGE_STUDIO_STORE).getIsImageStudioOpen?.() || false;
        if (isImageStudioOpen) {
            return 'image-studio';
        }
        // Check if AI agent context store exists (plugin is installed and active)
        if (!aiAgentContextStore) {
            return 'wp-admin';
        }
        // Case 1: Pretty permalinks - check if pathname includes /new
        // Example: /wp-admin/new/woocommerce/products
        if (pathname.includes('/new')) {
            return 'ciab-admin';
        }
        // Case 2: Plain permalinks - check if query string contains page=next-admin
        // Example: /wp-admin/admin.php?page=next-admin&p=%2Fwoocommerce%2Fproducts
        const urlParams = new URLSearchParams(search);
        if (urlParams.get('page') === 'next-admin') {
            return 'ciab-admin';
        }
    }
    catch (error) {
        // If the store doesn't exist or there's an error, fall back to wp-admin
    }
    return 'wp-admin';
}
/**
 * Resolve getData closures to fetch current context data.
 * This ensures we always send fresh data to wpcom without storing duplicates.
 *
 * @param {ContextEntry[]} entries - Context entries with getData closures to resolve
 * @return {ContextEntry[]} Resolved context entries with data populated
 */
function resolveContextEntries(entries) {
    return entries.map((entry) => {
        if (!entry.getData) {
            return entry;
        }
        try {
            return {
                ...entry,
                data: entry.getData(),
                getData: undefined,
            };
        }
        catch (error) {
            console.warn(`[Big Sky] Failed to resolve context entry ${entry.id}:`, error);
            return entry;
        }
    });
}
/**
 * Get context entries from ciab-admin store and resolve them.
 * Fetches entries from ai-agent-context store and calls getData closures to get current data.
 *
 * @param {any} aiAgentContextStore - The ai-agent-context WordPress data store
 * @return {ContextEntry[]} Resolved context entries with fresh entity data
 */
function getCiabAdminContext(aiAgentContextStore) {
    const contextEntries = aiAgentContextStore?.getContextEntries?.() || [];
    if (contextEntries.length === 0) {
        return [];
    }
    return resolveContextEntries(contextEntries);
}
/**
 * Detect and extract post entity when on post editor page
 * @return Post entity context or null
 */
function detectPostEntity() {
    try {
        const pathname = window.location.pathname; // '/wp-admin/post.php'
        const isPostEditor = pathname.match(/\/wp-admin\/post\.php/);
        if (!isPostEditor) {
            return null;
        }
        const editorStore = select(EDITOR_STORE);
        const postId = editorStore.getCurrentPostId();
        if (!postId) {
            return null;
        }
        return {
            id: 'post',
            type: 'entity',
            entityType: 'post',
            entityId: postId.toString(),
        };
    }
    catch (error) {
        console.error('[Big Sky] Error detecting post entity:', error);
        return null;
    }
}
/**
 * Detect and extract image entity when in Image Studio
 *
 * Note: We intentionally do NOT send the URL in context to prevent agent retry loops.
 * The backend fetches the current URL from the clientId (attachmentId) via
 * resolve_image_studio_url(). This avoids the agent seeing URL changes mid-turn
 * and deciding to retry operations.
 *
 * @return Image entity context or null
 */
function detectImageEntity() {
    try {
        const imageStudioSelect = select(IMAGE_STUDIO_STORE);
        if (!imageStudioSelect) {
            return null;
        }
        const attachmentId = imageStudioSelect.getImageStudioAttachmentId?.();
        const isOpen = imageStudioSelect.getIsImageStudioOpen?.() || false;
        const selectedStyle = imageStudioSelect.getSelectedStyle?.() || null;
        const selectedAspectRatio = imageStudioSelect.getSelectedAspectRatio?.() || null;
        const originalAttachmentId = imageStudioSelect.getOriginalAttachmentId?.() || null;
        // Generate mode = opened without an existing image
        const isGenerateMode = originalAttachmentId === null;
        const inputToolbarSelections = {};
        if (selectedStyle) {
            inputToolbarSelections.style = selectedStyle;
        }
        if (isGenerateMode && selectedAspectRatio) {
            inputToolbarSelections.aspect_ratio = selectedAspectRatio;
        }
        // Try to get the attachment entity from core store for metadata
        const coreDataStore = select(CORE_STORE);
        const attachment = attachmentId
            ? coreDataStore.getEntityRecord?.('postType', 'attachment', attachmentId)
            : null;
        if (!attachment) {
            return {
                imageStudio: {
                    isOpen,
                    id: attachmentId,
                    ...inputToolbarSelections,
                    metadata: {},
                },
            };
        }
        return {
            imageStudio: {
                isOpen,
                id: attachmentId,
                ...inputToolbarSelections,
                metadata: {
                    id: attachment.id,
                    title: attachment.title?.rendered || attachment.title,
                    alt: attachment.alt_text,
                    width: attachment.media_details?.width,
                    height: attachment.media_details?.height,
                    description: attachment.description?.rendered ||
                        attachment.description,
                },
            },
        };
    }
    catch (error) {
        return null;
    }
}
/**
 * Check if we're in a design editing environment.
 * This should align with the backend WP Orchestrator design-editing route settings.
 *
 * Matches:
 * - site-editor.php (Site editor / FSE)
 * - post.php?action=edit (Edit post)
 * - post-new.php (New post)
 * - /design/* routes in CIAB admin
 * - /types/<postType>/(edit|new) routes in CIAB admin (page/post editing)
 *
 * @see wp-content/lib/ai/agents/route-settings/wp-orchestrator/design-editing.php
 * @return boolean indicating if we're in a design editing environment
 */
export function isInDesignEditingEnvironment() {
    const pathname = window.location.pathname;
    const search = window.location.search;
    // Site editor (FSE)
    if (pathname.includes('site-editor.php')) {
        return true;
    }
    // Edit post (post.php?action=edit)
    if (pathname.includes('post.php') && search.includes('action=edit')) {
        return true;
    }
    // New post
    if (pathname.includes('post-new.php')) {
        return true;
    }
    // CIAB admin design routes (pretty permalinks)
    if (pathname.includes('/design/')) {
        return true;
    }
    // CIAB admin routes (plain permalinks via 'p' query param)
    const ciabPath = new URLSearchParams(search).get('p');
    if (ciabPath?.startsWith('/design/')) {
        return true;
    }
    // CIAB admin page/post editing routes: /types/<postType>/(edit|new)
    // Pretty permalinks: /wp-admin/new/types/page/edit/123
    if (/\/types\/[^/]+\/(edit|new)(\/|$)/.test(pathname)) {
        return true;
    }
    // Plain permalinks: ?p=/types/page/edit/123
    if (ciabPath && /^\/types\/[^/]+\/(edit|new)(\/|$)/.test(ciabPath)) {
        return true;
    }
    return false;
}
/**
 * Get block schemas for blocks used on the current page
 * @param pageContent - The current page content blocks
 * @return Array of block schema objects
 */
function getBlockSchemasFromPageContent(pageContent) {
    try {
        const { getBlockType } = select(blocksStore);
        const blockTypes = new Set();
        // Recursively collect all block types used on the page
        const collectBlockTypes = (blocks) => {
            if (!Array.isArray(blocks)) {
                return;
            }
            blocks.forEach((block) => {
                if (block.name) {
                    blockTypes.add(block.name);
                }
                if (block.innerBlocks) {
                    collectBlockTypes(block.innerBlocks);
                }
            });
        };
        collectBlockTypes(pageContent);
        // Get schemas for each unique block type (excluding core and jetpack blocks)
        return Array.from(blockTypes)
            .filter((blockName) => !blockName.startsWith('core/') &&
            !blockName.startsWith('jetpack/'))
            .map((blockName) => {
            const blockType = getBlockType(blockName);
            if (!blockType) {
                return null;
            }
            return {
                attributes: blockType.attributes,
                category: blockType.category,
                description: blockType.description,
                keywords: blockType.keywords,
                name: blockType.name,
                supports: blockType.supports,
                title: blockType.title,
                providesContext: blockType.providesContext,
            };
        })
            .filter((blockType) => blockType);
    }
    catch (error) {
        console.warn('[Big Sky] Error getting block schemas:', error);
        return [];
    }
}
/**
 * Get rich editor context when in the site editor
 * This includes block structure, schemas, selected block, etc.
 * @return Editor context object or null if not in site editor
 */
function getEditorContext() {
    if (!isInDesignEditingEnvironment()) {
        return null;
    }
    try {
        const aiStore = select(AI_STORE);
        const aiDispatch = dispatch(AI_STORE);
        // Check if the Big Sky store is available
        if (!aiStore) {
            console.warn('[Big Sky] AI store not available for editor context');
            return null;
        }
        // Get clientIdMap from store (or initialize empty)
        const clientIdMap = aiStore.getFullPageStructure?.()?.clientIdMap || {};
        // Get current page content with compressed block IDs
        const currentPageContent = getCurrentPageContent(aiDispatch, clientIdMap);
        // Get block schemas for blocks on the page
        const blockSchema = getBlockSchemasFromPageContent(currentPageContent);
        // Get available blocks
        const { getBlockTypes } = select(blocksStore);
        const blocks = getBlockTypes?.() || [];
        const availableBlocks = blocks.map((block) => ({
            name: block.name,
            description: block.description,
        }));
        // Get selected block client ID
        const { getSelectedBlockClientId } = select(blockEditorStore);
        const selectedClientId = getSelectedBlockClientId?.();
        // Find the short ID for the selected block
        const getSelectBlockShortId = (clientId) => {
            return Object.keys(clientIdMap).find((key) => clientIdMap[key] === clientId);
        };
        // Get current page/post ID
        const editorStore = select(EDITOR_STORE);
        const currentPageId = editorStore?.getCurrentPostId?.();
        // Get uploaded files from store
        const uploadedFiles = aiStore.getInputtedFiles?.()?.map((file) => file.id) || [];
        return {
            currentPageContent,
            blockSchema,
            availableBlocks,
            selectedBlockClientId: getSelectBlockShortId(selectedClientId) || '',
            current_page_id: currentPageId,
            uploadedFiles,
        };
    }
    catch (error) {
        console.warn('[Big Sky] Error getting editor context:', error);
        return null;
    }
}
/**
 * Get the complete client context for the AI agent
 * This includes current location and all context entries (sitemap, entities, etc.)
 *
 * @param options                   - Optional configuration
 * @param options.additionalContext - Additional context to merge into the client context (e.g., blockNotes: { isActive: true })
 */
export function getClientContext(options) {
    const aiAgentContextStore = select(AI_AGENT_CONTEXT_STORE);
    // Get all context entries from ciab-admin store (includes sitemap and entities)
    const contextEntries = getCiabAdminContext(aiAgentContextStore);
    // Detect post and image entities
    const postEntity = detectPostEntity();
    const imageEntity = detectImageEntity();
    // Get rich editor context if in site editor
    const editorContext = getEditorContext();
    // Build the context object
    const environment = detectEnvironment();
    const context = {
        url: window.location.href,
        pathname: window.location.pathname,
        search: window.location.search,
        environment,
        // Override model for CIAB Admin if configured
        ...(CIAB_ADMIN_MODEL && environment === 'ciab-admin'
            ? {
                constructorArguments: {
                    model: CIAB_ADMIN_MODEL,
                    ...(CIAB_ADMIN_REASONING_EFFORT
                        ? { reasoningEffort: CIAB_ADMIN_REASONING_EFFORT }
                        : {}),
                },
            }
            : {}),
        ...(contextEntries.length > 0 ? { contextEntries } : {}),
        ...(postEntity || {}),
        ...(imageEntity || {}),
        ...(options?.additionalContext || {}),
        ...(editorContext || {}),
    };
    return context;
}
